\title{The Crossing Law for Interval Hints:\\ Width Can Never Substitute for Reliability}
\author{Aristotle}
\date{October 2026}

\begin{document}

\begin{abstract}
We study a model of search with a fallible hint. A target lies in one of $M$ cells and has a min-law prior. An oracle names a window of $W$ cells and asserts that the target lies in it with probability $\alpha$. A searcher opens cells one at a time and pays the expected number of probes. We prove a \emph{displacement law} that gives the exact cost of every one of the $M!$ probe orders under the resulting two-valued posterior. From it we deduce that the Bayes-optimal searcher coincides with the committed (window-first) one, that for a strictly favoured window the optimal orders are exactly the window-first orders, and that interleaving is strictly dominated by the explicit margin $(a-b)W(W-1)/2$. Pricing the hinted search against the min-law blind cost $B_M=(M+1)(2M+1)/(6M)$ gives
\[
S_M(W,\alpha)=\frac{(M+1)(2M+1)}{3M\big((1-\alpha)M+W+1\big)},
\]
with continuum limit $S(\alpha,w)=2/(3(1-\alpha+w))$. Our main result is the \emph{crossing law}: speedup $s$ is attained if and only if $w\le \alpha-\amin(s)$, where $\amin(s)=1-2/(3s)$. This gives a hard reliability gate that no width can bypass. A finite-$M$ gate holds at every size and converges to the continuum gate. For a measured $5.19\times$ speedup the gate is $\alpha>0.87155$, and at $\alpha=0.90$ the crossing width is $\mu/M\approx 0.02845$. We determine the exact Bayes cost of the hint posterior. It shows that for the fully Bayes-optimal searcher the gate is two-sided, and an explicit witness shows that the one-sided gate fails outside the trusted regime. Finally, a pairing identity proves that the stipulated pricing is conservative for every posterior with the given window mass.
\end{abstract}

\maketitle

\section{Introduction}

Many searches are guided by a hint that is useful but not certain: a fault-localization tool flags a region of code, a learned index predicts a position with an error band, a heuristic narrows down a list of causes. Such a hint has two quality parameters. Its \emph{width} is how much of the space it names, and its \emph{reliability} is how often the target actually lies there. It is tempting to treat them as interchangeable. We show that in a natural, fully explicit model this intuition fails sharply. Reliability acts as a \emph{gate}: reaching speedup $s$ requires $\alpha>\amin(s)$, independently of width. Width only spends the surplus $\alpha-\amin(s)$, and the exchange is exactly linear.

Two technical steps make this rigorous. First, the Bayes-optimal probe order must be identified among all $M!$ orders; the displacement law does this. Second, the pricing model must be justified; a pairing identity shows that it is conservative.

\section{Model and an exchange lemma}

\begin{definition}[Cells, orders, cost]
Fix $M\ge 2$ cells $0,\dots,M-1$ and a weight vector $q$ (usually $q\ge0$, $\sum_j q_j=1$). A \emph{probe order} is a permutation $\sigma$, with $\sigma(i)$ the cell opened in slot $i$ (slots indexed from $0$). Its cost is
\[
\cost_q(\sigma)=\sum_{i=0}^{M-1}(i+1)\,q_{\sigma(i)},
\]
and the \emph{Bayes cost} is $\opt(q)=\min_\sigma\cost_q(\sigma)$ over all $M!$ orders.
\end{definition}

\begin{definition}[Min-law blind cost]
If the target position is the minimum of two independent uniform cells, the optimal hint-free searcher scans from the front at expected cost
\[
B_M=\sum_{j=1}^M\frac{(M-j+1)^2}{M^2}=\frac{(M+1)(2M+1)}{6M}\sim\frac M3 .
\]
\end{definition}

\begin{definition}[Hint posterior]
After relabelling, the oracle's window is $\{0,\dots,W-1\}$ with $0<W<M$, and its reliability is $\alpha\in[0,1]$. The \emph{stipulated hint posterior} is the two-valued posterior with $q_j=a=\alpha/W$ for $j<W$ and $q_j=b=(1-\alpha)/(M-W)$ for $j\ge W$. The \emph{window slots} of $\sigma$ are $\mathcal W(\sigma)=\{i:\sigma(i)<W\}$, a set of exactly $W$ slots. The \emph{committed} order is the identity.
\end{definition}

\begin{theorem}[Exchange lemma]\label{thm:exchange}
Let $T,R$ be finite sets with $|T|=|R|$, let $f$ be a nonnegative integer weight, and let $c\in\mathbb N$. Suppose $f\ge c$ on $T\setminus R$ and $f+1\le c$ on $R\setminus T$. Then $\sum_R f+|T\setminus R|\le\sum_T f$.
\end{theorem}
\begin{proof}
We have $|T\setminus R|=|R\setminus T|=k$, and the sums over $T\cap R$ cancel. Then $\sum_{R\setminus T}f+k=\sum_{R\setminus T}(f+1)\le kc\le\sum_{T\setminus R}f$.
\end{proof}

\begin{theorem}[Position-sum bound]\label{thm:possum}
For $0\le k\le M$ and any set $U$ of $k$ slots,
\[
\frac{k(k+1)}2+\#\{i\in U:i\ge k\}\le\sum_{i\in U}(i+1).
\]
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:exchange} with $T=U$, $R=\{0,\dots,k-1\}$, $f(i)=i$, $c=k$, and then add $k$ to both sides.
\end{proof}

\section{The displacement law and optimal search}

\begin{lemma}\label{lem:cost}
Under a two-valued posterior $(a,b)$, $\cost(\sigma)=b\,\frac{M(M+1)}2+(a-b)\sum_{i\in\mathcal W(\sigma)}(i+1)$.
\end{lemma}
\begin{proof}
Write $q_{\sigma(i)}=b+(a-b)\mathbf 1[i\in\mathcal W(\sigma)]$ and sum against $i+1$.
\end{proof}

\begin{theorem}[Displacement law]\label{thm:disp}
For every two-valued posterior $(a,b)$, every $W\le M$ and every order $\sigma$,
\[
\cost(\sigma)-\cost(\mathrm{committed})=(a-b)\Big(\sum_{i\in\mathcal W(\sigma)}(i+1)-\frac{W(W+1)}2\Big).
\]
\end{theorem}
\begin{proof}
Subtract Lemma~\ref{lem:cost} at the identity, whose window-slot sum is $W(W+1)/2$.
\end{proof}

\begin{theorem}[Misplacement cost; Bayes $=$ Committed]\label{thm:bayes}
Let $m(\sigma)=\#\{i\in\mathcal W(\sigma):i\ge W\}$. If $a\ge b$, then
$\cost(\mathrm{committed})+(a-b)\,m(\sigma)\le\cost(\sigma)$ for every $\sigma$. Hence $\opt=\cost(\mathrm{committed})$.
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:possum} for $U=\mathcal W(\sigma)$ with Theorem~\ref{thm:disp}.
\end{proof}

\begin{theorem}[Bayes orders]\label{thm:bayesiff}
If $a>b$, an order $\sigma$ is Bayes-optimal if and only if $\sigma(i)<W\Rightarrow i<W$.
\end{theorem}
\begin{proof}
Window-first orders have zero displacement. Any other order has $m(\sigma)\ge1$, so its cost is at least $\opt+(a-b)>\opt$.
\end{proof}

There are therefore exactly $W!\,(M-W)!$ optimal orders; for $M=6$, $W=2$, $\alpha=0.7$ enumeration finds exactly $48$.

\begin{lemma}[Realizability]
For every set $T$ of $W$ slots there is an order $\sigma$ with $\mathcal W(\sigma)=T$.
\end{lemma}

\begin{theorem}[Interleaving]\label{thm:inter}
Let $2W\le M$. Orders whose window slots are $\{0,2,\dots,2W-2\}$ exist, and each of them satisfies
\[
\cost(\sigma)=\cost(\mathrm{committed})+(a-b)\frac{W(W-1)}2 .
\]
If $W\ge2$ and $a>b$, then $\opt<\cost(\sigma)$.
\end{theorem}
\begin{proof}
The slot numbers $1,3,\dots,2W-1$ sum to $W^2$, and $W^2-W(W+1)/2=W(W-1)/2$.
\end{proof}

\begin{example}
For $M=8$, $W=3$, $a=1/5$, $b=1/25$, the interleaved excess is $12/25$.
\end{example}

For the stipulated posterior, Lemma~\ref{lem:cost} at the identity gives the \emph{two-number cost}
\[
C_M(W,\alpha)=\alpha\frac{W+1}2+(1-\alpha)\frac{M+W+1}2=\frac{W+1+(1-\alpha)M}2 .
\]

\section{The crossing law}

\begin{definition}
For $1-\alpha+w>0$ and $s>0$ set $S(\alpha,w)=\dfrac{2}{3(1-\alpha+w)}$ and $\amin(s)=1-\dfrac{2}{3s}$.
\end{definition}

\begin{theorem}[The crossing law]\label{thm:crossing}
For $s>0$ and $1-\alpha+w>0$:\qquad $s\le S(\alpha,w)\iff w\le\alpha-\amin(s)$.
\end{theorem}
\begin{proof}
Clearing the positive denominator, $s\le S$ is equivalent to $1-\alpha+w\le 2/(3s)$, which rearranges to the claim.
\end{proof}

\begin{corollary}[Reliability gate]
If $w>0$ and $s\le S(\alpha,w)$, then $\alpha>\amin(s)$.
\end{corollary}

\begin{corollary}[Width cannot substitute for reliability]
If $\alpha\le\amin(s)$, then $S(\alpha,w)<s$ for every $w>0$.
\end{corollary}
\begin{proof}
Here $1-\alpha+w\ge 2/(3s)+w>2/(3s)$.
\end{proof}

\begin{corollary}[Iso-speedup lines]
$S(\alpha,w)=s\iff w=\alpha-\amin(s)$. For $\alpha>\amin(s)$, the crossing width $w^\star=\alpha-\amin(s)>0$ attains $S(\alpha,w^\star)=s$.
\end{corollary}

\begin{proposition}[A measured $5.19\times$ speedup]
$0.87154<\amin(5.19)<0.87155$; moreover $0.02845<0.9-\amin(5.19)<0.02846$ and $S(0.9,\,0.9-\amin(5.19))=5.19$.
\end{proposition}
\begin{proof}
$\amin(5.19)=1-2/15.57=0.8715478\ldots$
\end{proof}

A $5.19\times$ gain thus forces hints that are correct more than $87.15\%$ of the time, at any width. At $90\%$ reliability it corresponds to windows of about $2.85\%$ of the space. This matches an independent numerical estimate ($\alpha\approx0.90$, $\mu/M\approx0.028$).

\section{Finite-\texorpdfstring{$M$}{M} theory}

\begin{theorem}[Closed form]
For $0<W<M$, $S_M(W,\alpha):=B_M/C_M(W,\alpha)=\dfrac{(M+1)(2M+1)}{3M((1-\alpha)M+W+1)}$.
\end{theorem}

At $M=300$, $W=9$, $\alpha=0.9$ the closed form equals the brute-force sum exactly: $S=5.02503\ldots$

\begin{theorem}[Finite reliability gate]\label{thm:finitegate}
Let $\amin^M(s)=1-\dfrac{(M+1)(2M+1)}{3M^2s}$. If $0<W<M$, $\alpha\le1$, $s>0$ and $s\le S_M(W,\alpha)$, then $\alpha>\amin^M(s)$.
\end{theorem}
\begin{proof}
The hypothesis gives $(1-\alpha)M+W+1\le(M+1)(2M+1)/(3Ms)$. Since $W+1>0$, $(1-\alpha)M$ is strictly smaller; divide by $M$.
\end{proof}

\begin{theorem}[Continuum limits]
$\amin^M(s)\to\amin(s)$, and if $W_M/M\to w$ with $1-\alpha+w>0$ then $S_M(W_M,\alpha)\to S(\alpha,w)$.
\end{theorem}

