\begin{tabular}{@{}lcccccc@{}}
\toprule
$M$ & $10$ & $100$ & $300$ & $10^3$ & $10^4$ & $\infty$\\
\midrule
$\amin^M(5.19)$ & $0.85164$ & $0.86962$ & $0.87090$ & $0.87136$ & $0.87153$ & $0.87155$\\
\bottomrule
\end{tabular}
\end{center}

\section{The fully Bayesian searcher: a two-sided gate}

\begin{theorem}[Exact Bayes cost]\label{thm:bayesexact}
For $0<W<M$ and every $\alpha$,
\[
\opt=\min\Big(\frac{W+1+(1-\alpha)M}2,\ \frac{M-W+1+\alpha M}2\Big).
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:cost}, the cost is affine in the window-slot sum $\Sigma$, and $W(W+1)/2\le\Sigma\le W(2M-W+1)/2$. If $a\ge b$, the minimum is the committed cost. If $a<b$, it is the cost of the outside-first order, namely $(1-\alpha)\frac{M-W+1}2+\alpha(M-W+\frac{W+1}2)=\frac{M-W+1+\alpha M}2$. Both values are attained.
\end{proof}

For $M=6$, all $720$ orders and $55$ cells ($W=1..5$, $\alpha=0,0.1,\dots,1$) agree with this formula.

\begin{theorem}[Two-sided Bayes gate]
If $0<W<M$, $0\le\alpha\le1$, $s>0$ and $s\le B_M/\opt$, then $\alpha>\amin^M(s)$ or $1-\alpha>\amin^M(s)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:bayesexact}, $\opt$ is one of two committed costs. The second equals $\frac{(M-W)+1+(1-(1-\alpha))M}2$, the committed cost of the complementary hint with width $M-W$ and reliability $1-\alpha$. Apply Theorem~\ref{thm:finitegate} to whichever hint attains the minimum.
\end{proof}

\begin{proposition}[The one-sided gate fails]
For $M=4$, $W=2$, $\alpha=0$: $B_4/\opt=(15/8)/(3/2)=5/4$, yet $\amin^4(5/4)=1/4>\alpha$.
\end{proposition}

\begin{corollary}[Trusted regime]
If $W\le\alpha M$ and $\alpha\le1$, then $\opt=C_M(W,\alpha)$, and $s\le B_M/\opt$ implies $\alpha>\amin^M(s)$.
\end{corollary}

\section{The stipulated pricing is conservative}

\begin{definition}
The \emph{block reversal} $\rho$ opens the window in reverse order $W-1,\dots,0$ and then the outside in reverse order $M-1,\dots,W$.
\end{definition}

\begin{theorem}[Pairing identity]
For any $q$ with $\sum_{j<W}q_j=\alpha$ and $\sum_jq_j=1$:\quad $\cost_q(\mathrm{committed})+\cost_q(\rho)=W+1+(1-\alpha)M$.
\end{theorem}
\begin{proof}
A window cell $j$ occupies slots $j+1$ and $W-j$ (total $W+1$). An outside cell occupies slots $j+1$ and $M+W-j$ (total $M+W+1$). Summing gives $(W+1)\alpha+(M+W+1)(1-\alpha)$.
\end{proof}

\begin{corollary}
$\opt(q)\le C_M(W,\alpha)$ for every such $q$.
\end{corollary}

\begin{theorem}[Conservative pricing]
If $0<W<M$, $q\ge0$, $\sum_jq_j=1$ and $\sum_{j<W}q_j=\alpha$, then $S_M(W,\alpha)\le B_M/\opt(q)$.
\end{theorem}
\begin{proof}
Here $\opt(q)\ge1>0$, so the previous corollary inverts.
\end{proof}

In $300$ random posteriors on $6$ cells, $\opt(q)/C_M$ never exceeded $1$. Empirically, conditioning in a way that follows the shape of the prior raised an estimated speedup from $5.56\times$ to $7.62\times$. The crossing law is therefore a guaranteed benchmark, not a universal necessary condition for arbitrary hint semantics.

\section{Algorithms}

\begin{enumerate}
\item \textbf{Exact pricing} ($O(1)$). Compute $B_M$, $C_{\rm in}=(W+1+(1-\alpha)M)/2$ and $C_{\rm out}=(M-W+1+\alpha M)/2$. Return $S_M=B_M/C_{\rm in}$ and the Bayes speedup $B_M/\min(C_{\rm in},C_{\rm out})$.
\item \textbf{Gate test}. If $\alpha\le\amin(s)$, report \emph{unreachable at any width}. Otherwise report the width budget $\alpha-\amin(s)$.
\item \textbf{Displacement evaluation} ($O(M)$). Compute the window-slot sum $\Sigma$. Then $\cost=\cost(\mathrm{committed})+(a-b)(\Sigma-W(W+1)/2)$.
\item \textbf{Inverting a measured speedup}. The implied width is $w=\alpha-\amin(s)$. If it is not positive, the assumed $\alpha$ is inconsistent with the measurement.
\end{enumerate}

\section{Discussion}

The continuum denominator $1-\alpha+w$ makes unreliability and width additive costs. Even at zero width, unreliability alone caps the speedup at $2/(3(1-\alpha))$. The displacement law makes the optimum explicit by reducing the landscape over $M!$ orders to a single integer. The crossing law concerns the stipulated pricing; real posteriors can only do better. For a fully Bayesian searcher the gate is two-sided. Among the corrections made along the way, the most instructive was a ``Bayes'' computation that marginalized over the hint instead of conditioning on it, which collapses to the hint-blind floor.

\section{Future directions}

\begin{enumerate}
\item \emph{Strict conservative pricing} for prior-proportional hints, with a $\Theta(M)$ gap, via the pairing identity and Chebyshev's sum inequality.
\item \emph{Two-sided gate as a general Bayes law}: the reachable set of $\alpha$ is a union of two half-lines.
\item \emph{Multi-window crossing law}: a polyhedral gate for nested windows with cumulative reliabilities.
\item \emph{Misspecification}: if the claimed reliability is $\alpha$ but the true one is $\beta$, speedup $s$ is reachable iff $w\le\beta-\amin(s)$.
\end{enumerate}

\section{Conclusion}

For a min-law target and an interval hint of width $w$ and reliability $\alpha$,
\[
s\le\frac{2}{3(1-\alpha+w)}\iff w\le\alpha-\Big(1-\frac2{3s}\Big).
\]
Width can never substitute for reliability.

