from fractions import Fraction
from typing import Optional


def alpha_min(s: Fraction) -> Fraction:
    return 1 - Fraction(2) / (3 * s)


def alpha_min_finite(M: int, s: Fraction) -> Fraction:
    return 1 - Fraction((M + 1) * (2 * M + 1)) / (3 * M * M * s)


def gate_test(s: Fraction, alpha: Fraction, w: Fraction,
              M: Optional[int] = None) -> str:
    """Decide reachability of speedup s by a hint (alpha, w) via the crossing law."""
    g = alpha_min(s)
    if M is not None and alpha <= alpha_min_finite(M, s):
        return f"unreachable at any width (finite gate {float(alpha_min_finite(M, s)):.5f})"
    if alpha <= g:
        return f"unreachable at any width: alpha <= alpha_min(s) = {float(g):.5f}"
    budget = alpha - g
    verdict = "reachable" if w <= budget else "too wide"
    return f"{verdict}: width budget alpha - alpha_min(s) = {float(budget):.5f}"


def implied_width(s: Fraction, alpha: Fraction) -> Optional[Fraction]:
    """Invert a measured speedup: the effective width fraction implied by reliability alpha."""
    w = alpha - alpha_min(s)
    return w if w > 0 else None


if __name__ == "__main__":
    s = Fraction(519, 100)
    print(gate_test(s, Fraction(87, 100), Fraction(1, 1000)))
    print(gate_test(s, Fraction(9, 10), Fraction(2, 100)))
    print(float(implied_width(s, Fraction(9, 10))))   # 0.0284522...
